import { operation, resource } from "@tinker/core";
import { database } from "./database.ts";
import { sendMail } from "./mail.ts";
import { authSettings, requestHeaders } from "@tinker/start/server";
export { authSettings } from "@tinker/start/server";
import { raise } from "../errors.ts";
export const auth = resource({
  label: "auth",
  target: "session",
  depends: { database, settings: authSettings, send: sendMail },
  factory: async ({ database, settings, send }) => {
    const [{ betterAuth }, { drizzleAdapter }, { tanstackStartCookies }, schema] =
      await Promise.all([
        import("better-auth"),
        import("better-auth/adapters/drizzle"),
        import("better-auth/tanstack-start"),
        import("./schema.ts"),
      ]);
    return betterAuth({
      baseURL: settings.origin,
      secret: settings.secret,
      database: drizzleAdapter(database, { provider: "pg", schema }),
      emailAndPassword: {
        enabled: true,
        sendResetPassword: async ({ user, url }) => {
          await send.run({ input: { to: user.email, subject: "Reset your password", text: url } });
        },
      },
      emailVerification: {
        sendOnSignUp: true,
        sendVerificationEmail: async ({ user, url }) => {
          await send.run({ input: { to: user.email, subject: "Check your email", text: url } });
        },
      },
      plugins: [tanstackStartCookies()],
    });
  },
});
export const principal = resource({
  label: "request.principal",
  target: "session",
  depends: { auth, headers: requestHeaders },
  factory: async ({ auth, headers }) => (await auth.api.getSession({ headers }))?.user ?? null,
});
export const currentUser = resource({
  label: "request.currentUser",
  target: "session",
  depends: { principal },
  factory: async ({ principal }) => {
    if (principal === null) raise("SignInRequired", {});
    return principal;
  },
});
export const readAccount = operation({
  label: "readAccount",
  depends: { principal },
  run: async ({ principal }) => principal?.id ?? null,
});

import { pgTable, text, timestamp, boolean, index } from "drizzle-orm/pg-core";
export const user = pgTable("user", {
  id: text().primaryKey(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  image: text(),
  createdAt: timestamp().notNull().defaultNow(),
  updatedAt: timestamp().notNull().defaultNow(),
});
export const session = pgTable(
  "session",
  {
    id: text().primaryKey(),
    expiresAt: timestamp().notNull(),
    token: text().notNull().unique(),
    createdAt: timestamp().notNull().defaultNow(),
    updatedAt: timestamp().notNull().defaultNow(),
    ipAddress: text(),
    userAgent: text(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_user_id").on(table.userId)],
);
export const account = pgTable(
  "account",
  {
    id: text().primaryKey(),
    accountId: text().notNull(),
    providerId: text().notNull(),
    userId: text()
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text(),
    refreshToken: text(),
    idToken: text(),
    accessTokenExpiresAt: timestamp(),
    refreshTokenExpiresAt: timestamp(),
    scope: text(),
    password: text(),
    createdAt: timestamp().notNull().defaultNow(),
    updatedAt: timestamp().notNull().defaultNow(),
  },
  (table) => [index("account_user_id").on(table.userId)],
);
export const verification = pgTable(
  "verification",
  {
    id: text().primaryKey(),
    identifier: text().notNull(),
    value: text().notNull(),
    expiresAt: timestamp().notNull(),
    createdAt: timestamp().notNull().defaultNow(),
    updatedAt: timestamp().notNull().defaultNow(),
  },
  (table) => [index("verification_identifier").on(table.identifier)],
);

import { z } from "zod";
export const credentials = z.object({
  mode: z.enum(["signup", "signin"]),
  name: z.string().max(80),
  email: z.email(),
  password: z.string().min(8),
});

import { Counter } from "./Counter.tsx";
import { Link } from "@tanstack/react-router";
import { useData, useRun } from "@tinker/react";
import { profile, pending, notice, authMode } from "./state.ts";
import { signIn, setAuthMode } from "./auth-actions.ts";
import { errorText } from "./error-text.ts";
import { Button } from "./ui/button.tsx";
import { Input } from "./ui/input.tsx";
import { Card, CardHeader, CardTitle, CardContent } from "./ui/card.tsx";
function AccountForm() {
  const mode = useData(authMode);
  const changeMode = useRun(setAuthMode);
  const action = useRun(signIn);
  const busy = useData(pending);
  return (
    <form
      className="space-y-5"
      onSubmit={(event) => {
        event.preventDefault();
        const form = new FormData(event.currentTarget);
        action.run({
          rawInput: {
            mode,
            name: form.get("name") ?? "",
            email: form.get("email"),
            password: form.get("password"),
          },
        });
      }}
    >
      <div className="flex gap-1 rounded-lg bg-muted p-1">
        <Button
          type="button"
          variant={mode === "signup" ? "outline" : "ghost"}
          className="flex-1 text-xs"
          disabled={busy}
          aria-pressed={mode === "signup"}
          onClick={() => changeMode.run({ input: "signup" })}
        >
          Make an account
        </Button>
        <Button
          type="button"
          variant={mode === "signin" ? "outline" : "ghost"}
          className="flex-1 text-xs"
          disabled={busy}
          aria-pressed={mode === "signin"}
          onClick={() => changeMode.run({ input: "signin" })}
        >
          Sign in
        </Button>
      </div>
      {mode === "signup" && (
        <label className="grid gap-2 text-sm font-medium">
          Name
          <Input
            name="name"
            autoComplete="name"
            required
            maxLength={80}
            placeholder="Ada Lovelace"
            disabled={busy}
          />
        </label>
      )}
      <label className="grid gap-2 text-sm font-medium">
        Email
        <Input
          name="email"
          type="email"
          autoComplete="email"
          required
          placeholder="ada@example.com"
          disabled={busy}
        />
      </label>
      <label className="grid gap-2 text-sm font-medium">
        Password
        <Input
          name="password"
          type="password"
          autoComplete={mode === "signup" ? "new-password" : "current-password"}
          minLength={8}
          required
          placeholder="At least 8 characters"
          disabled={busy}
        />
      </label>
      <Button className="w-full" disabled={busy}>
        {busy ? "Working…" : mode === "signup" ? "Make account" : "Sign in"}
      </Button>
      <p role="alert" className="text-sm text-destructive">
        {errorText(action.error)}
      </p>
    </form>
  );
}
export function App() {
  const current = useData(profile);
  const message = useData(notice);
  return (
    <main className="mx-auto max-w-2xl space-y-6 px-5 py-8">
      <header>
        <p className="text-xs font-semibold tracking-widest text-muted-foreground">STARTER</p>
        <h1 className="mt-3 text-2xl font-semibold">A shared counter. Your private space.</h1>
      </header>
      <Counter />
      <Card>
        <CardHeader>
          <CardTitle>
            <h2>{current ? "Your account" : "Sign in or make an account"}</h2>
          </CardTitle>
        </CardHeader>
        <CardContent>
          {current ? (
            <div className="flex gap-3">
              <Button asChild>
                <Link to="/profile">Open profile</Link>
              </Button>
              <Button asChild variant="outline">
                <Link to="/todos">Open private list</Link>
              </Button>
            </div>
          ) : (
            <AccountForm />
          )}
          <p role="status" className="mt-3 text-sm">
            {message}
          </p>
        </CardContent>
      </Card>
    </main>
  );
}

import { operation, resource } from "@tinker/core";
import { z } from "zod";
import { pending, notice, authMode } from "./state.ts";
import { syncClient, snapshotLoader } from "@tinker/start/client";
import { credentials } from "../contracts/credentials.ts";
import { raise } from "../errors.ts";
const modeInput = z.enum(["signup", "signin"]);
export const authClient = resource({
  label: "browser.auth",
  factory: async () => {
    const { createAuthClient } = await import("better-auth/react");
    return createAuthClient();
  },
});
export const signIn = operation({
  label: "signIn",
  input: (raw: unknown) => {
    const parsed = credentials.safeParse(raw);
    if (!parsed.success) raise("BadInput", { reason: "Check your email and password." });
    return parsed.data;
  },
  depends: {
    client: authClient,
    sync: syncClient,
    snapshots: snapshotLoader,
    pending: pending.controller,
    notice: notice.controller,
  },
  run: async ({ client, sync, snapshots, pending, notice }, { defer, input, signal, log }) => {
    pending.set(true);
    notice.set("");
    defer(() => pending.set(false));
    const change = snapshots.beginAccountChange();
    defer(() => snapshots.endAccountChange(change));
    sync.leave();
    const result =
      input.mode === "signup"
        ? await client.signUp.email(input, { signal: signal })
        : await client.signIn.email(input, { signal: signal });
    if (result.error) raise("AuthFailed", { message: result.error.message ?? "Sign in failed." });
    await snapshots.completeAccountChange(signal, change);
    notice.set("You are signed in. Open your profile or private list.");
    log("account.signedIn");
  },
});
export const signOut = operation({
  label: "signOut",
  depends: { client: authClient, sync: syncClient, notice: notice.controller },
  run: async ({ client, sync, notice }, { signal }) => {
    const result = await client.signOut({ fetchOptions: { signal: signal } });
    if (result.error) raise("AuthFailed", { message: result.error.message ?? "Sign out failed." });
    sync.leave();
    notice.set("You are signed out. Committed changes remain saved.");
  },
});
export const setAuthMode = operation({
  label: "setAuthMode",
  input: (raw: unknown) => modeInput.parse(raw),
  depends: { mode: authMode.controller },
  run: ({ mode }, { input }) => mode.set(input),
});

import { createFileRoute } from "@tanstack/react-router";
import { App } from "../frontend/App.tsx";
export const Route = createFileRoute("/")({
  gcTime: 0,
  loader: ({ context }) => context.bootstrap(),
  component: App,
});
